for r in range(H-max(dr for dr,dc in mask)):
 for c in range(W-max(dc for dr,dc in mask)):
  if all(grid[r+dr][c+dc]==0 for dr,dc in mask): matches.append((r,c))
out=[row[:] for row in grid]
